Create a registry data structure to map CSS rules to DOM elements:

```typescript
interface ClassRegistry {
  [className: string]: {
    cssRule: CSSStyleRule;
    elements: Element[];
    originalClassName: string;
  }
}

async function buildRegistry(): Promise<ClassRegistry> {
  const registry: ClassRegistry = {};
  const selectors = await discoverWithRetry();

  debug(`Discovered ${selectors.length} tw-enigma selectors`);

  // Limit registry size to prevent performance issues
  const limitedSelectors = selectors.slice(0, CONFIG.MAX_REGISTRY_SIZE);

  for (const { rule, className } of limitedSelectors) {
    try {
      // Find all elements with this class
      const elements = Array.from(document.querySelectorAll(`.${className}`));

      if (elements.length > 0) {
        registry[className] = {
          cssRule: rule,
          elements,
          originalClassName: className
        };
      }
    } catch (e) {
      debug(`Error mapping elements for class ${className}`, e);
    }
  }

  debug(`Built registry with ${Object.keys(registry).length} active classes`);
  return registry;
}
```

Implement a registry cleanup function to prevent memory leaks:

```typescript
function cleanupRegistry(registry: ClassRegistry): void {
  for (const className in registry) {
    // Filter out elements that are no longer in the DOM
    registry[className].elements = registry[className].elements.filter(el => el.isConnected);

    // Remove classes with no elements
    if (registry[className].elements.length === 0) {
      delete registry[className];
    }
  }

  debug(`Registry cleanup complete, ${Object.keys(registry).length} classes remaining`);
}
```

Implement functions to generate random class names and check for conflicts:

```typescript
function generateRandomClassName(length = 1): string {
  let result = '';
  const charset = CONFIG.CHARSET;

  // First character must be a letter (a-z)
  result += charset.substring(0, 26).charAt(Math.floor(Math.random() * 26));

  // If length > 1, add more random characters (can include numbers)
  for (let i = 1; i < length; i++) {
    result += charset.charAt(Math.floor(Math.random() * charset.length));
  }

  return result;
}

function generateUniqueClassName(registry: ClassRegistry, preferredLength = 1): string {
  // Start with preferred length, increase if needed to find unique name
  let length = preferredLength;
  let attempts = 0;
  let className;

  do {
    className = generateRandomClassName(length);
    attempts++;

    // If we've tried too many times at this length, increase length
    if (attempts > 10) {
      length++;
      attempts = 0;
    }
  } while (registry[className]);

  return className;
}
```

Implement the function to scramble a single class:

```typescript
function scrambleClass(registry: ClassRegistry, originalClassName: string): void {
  const entry = registry[originalClassName];
  if (!entry) return;

  try {
    // Generate a new unique class name
    const newClassName = generateUniqueClassName(registry, originalClassName.length);

    // Update the CSS rule
    entry.cssRule.selectorText = `.${newClassName}`;

    // Update all DOM elements
    for (const element of entry.elements) {
      element.classList.remove(originalClassName);
      element.classList.add(newClassName);
    }

    // Update registry with new class name
    registry[newClassName] = entry;
    delete registry[originalClassName];
  } catch (e) {
    debug(`Error scrambling class ${originalClassName}`, e);
  }
}
```

Implement the main scramble function that updates all classes in the registry:

```typescript
function scrambleAllClasses(registry: ClassRegistry): void {
  // Get all current class names (before we start modifying the registry)
  const classNames = Object.keys(registry);

  // Process each class
  for (const className of classNames) {
    if (registry[className]) { // Check again as registry might have changed
      scrambleClass(registry, className);
    }
  }
}
