// In the CLI codebase
import { existsSync } from 'fs';
import { resolve } from 'path';

async function detectScramblePackage(): Promise<string | null> {
  try {
    // Try to resolve the package path
    const packagePath = resolve(process.cwd(), 'packages-private/scramble/dist/scramble.min.js');

    // Check if the file exists
    if (existsSync(packagePath)) {
      return packagePath;
    }

    // Alternative resolution methods
    try {
      // Try using require.resolve (works in Node.js environments)
      return require.resolve('@tw-enigma/scramble/dist/scramble.min.js');
    } catch (e) {
      // Package not found via require.resolve
    }

    return null;
  } catch (e) {
    console.warn('⚠️ Error detecting scramble package:', e);
    return null;
  }
}

// Usage in CLI command handler
async function handleScrambleFlag(options: any): Promise<void> {
  if (options.scramble) {
    const scramblePackagePath = await detectScramblePackage();

    if (scramblePackagePath) {
      console.log('✅ Scramble package found at:', scramblePackagePath);
      await integrateScrambleEffect(scramblePackagePath, options);
    } else {
      console.warn('⚠️ Scramble effect requires @tw-enigma/scramble package, which was not found. Skipping scramble integration.');
      // Continue normal CLI operation without scramble
    }
  }
}
