Implement the main integration function in the CLI:

```typescript
// In the CLI codebase
import { copyFileSync, mkdirSync } from 'fs';
import { dirname, join } from 'path';
import { execSync } from 'child_process';

async function integrateScrambleEffect(
  scramblePackagePath: string,
  options: any
): Promise<void> {
  try {
    const buildDir = options.outDir || 'dist';
    const assetsDir = join(buildDir, 'assets');
    const configuredScriptPath = join(assetsDir, 'enigma-scramble.js');

    // Ensure assets directory exists
    mkdirSync(assetsDir, { recursive: true });

    // Build scramble package if needed
    if (options.buildScramble) {
      console.log('Building scramble package...');
      execSync('pnpm --filter @tw-enigma/scramble build');
    }

    // Inject configuration and copy to build output
    await injectScrambleConfiguration(
      scramblePackagePath,
      configuredScriptPath,
      {
        scrambleSpeed: options.scrambleSpeed,
        scrambleDebug: options.scrambleDebug,
        scrambleMode: options.scrambleMode,
        scrambleCharset: options.scrambleCharset
      }
    );

    // Inject script into HTML files
    await injectScrambleIntoHtmlFiles(buildDir, configuredScriptPath);

    console.log('✅ Scramble effect integration complete');
  } catch (e) {
    console.error('❌ Error integrating scramble effect:', e);
  }
}

// Add CLI command options
function addScrambleOptions(program: any) {
  return program
    .option('--scramble', 'Enable scramble effect')
    .option('--scramble-speed <ms>', 'Scramble speed in milliseconds (50-1000)', parseInt)
    .option('--scramble-debug', 'Enable debug logging for scramble effect')
    .option('--scramble-mode <mode>', 'Scramble mode (currently only "all" supported)')
    .option('--scramble-charset <charset>', 'Character set for scramble effect');
}
